  const hasInsufficientSamples = measured.some((m) => m.baseline.samples.length < 2
    || m.candidate.samples.length < 2);
  return hasMeasureErrors || hasInsufficientSamples ? EXIT_MEASURE_ERROR : EXIT_OK;
}

module.exports = {
  abSuite,
  loadManifest,
};

